-- One-time rename for saved games, matching lib/historical-data.ts. It changes only
-- game IDs and source fields, never names or other text:
--  * performance IDs `prime-rushmore:<athlete>:<season>:<game>` -> `historical:...`, in
--    performance objects (`"id":`) and in the no-repeat ledger (`"used":[...]`, first and
--    later elements);
--  * historical `sourceUrl` / `sourceUrls[0]` links from the old source repository ->
--    `/historical-coverage.json#<revision>/<file>:L<line>` (one pair per source file),
--    and `sourceUrls[1]` (the old validation report) -> `/historical-coverage.json`.
-- Every pattern starts at a quote that belongs to the JSON structure (a key, or an array
-- element after `[` or `,`). Saved state is written with JSON.stringify, which stores a
-- quote inside text as \", so these patterns cannot match inside a typed league or team
-- name, or the activity text built from names. A row is written only when its text
-- changes, so rows without historical games (including demo_scoring_backups, which only
-- ever holds unplayed drafts and is not touched) stay byte-identical, and a second run
-- changes nothing. Revisions are left alone: the column must keep matching
-- `state.revision`, and the server rebuilds each next state from the stored row.
-- tests/migration-0008.test.ts runs this file twice against rows saved by the previous
-- app version.
UPDATE `leagues` SET `state` = `renamed`.`state`
FROM (SELECT `rowid` AS `id`, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`state`,
  '"id":"prime-rushmore:',
  '"id":"historical:'),
  '"used":["prime-rushmore:',
  '"used":["historical:'),
  '","prime-rushmore:',
  '","historical:'),
  '"sourceUrl":"https://github.com/Jonathan94110/prime-rushmore/blob/bbfc22cc51b0f0a80aff2c1d6d7f4d32b219d356/fantasy-legends/data/sheets/qb_gamelogs_1950s.csv#L',
  '"sourceUrl":"/historical-coverage.json#bbfc22cc51b0f0a80aff2c1d6d7f4d32b219d356/qb_gamelogs_1950s.csv:L'),
